"use client";

import { useState } from "react";

type SearchPanel = "where" | "when" | "who" | null;

export default function SearchBar() {
  const [activePanel, setActivePanel] = useState<SearchPanel>(null);

  const [destination, setDestination] = useState("");
  const [guests, setGuests] = useState({
    adults: 0,
    children: 0,
    infants: 0,
    pets: 0,
  });

  const togglePanel = (panel: SearchPanel) => {
    setActivePanel((current) =>
      current === panel ? null : panel
    );
  };

  const updateGuest = (
    type: keyof typeof guests,
    amount: number
  ) => {
    setGuests((current) => ({
      ...current,
      [type]: Math.max(0, current[type] + amount),
    }));
  };

  const totalGuests =
    guests.adults + guests.children;

  return (
    <div
      className="search-wrapper"
      onClick={() => {
        if (activePanel) {
          setActivePanel(null);
        }
      }}
    >

      {/* =================================
          MOBILE SEARCH
      ================================= */}

      <button
        className="mobile-search"
        onClick={(event) => {
          event.stopPropagation();
          setActivePanel("where");
        }}
      >
        <span className="mobile-search-icon">⌕</span>

        <span className="mobile-search-text">
          Start your search
        </span>
      </button>


      {/* =================================
          DESKTOP SEARCH
      ================================= */}

      <div
        className="search-bar"
        onClick={(event) => event.stopPropagation()}
      >

        {/* WHERE */}

        <button
          className={`search-item search-location ${
            activePanel === "where"
              ? "search-item-active"
              : ""
          }`}
          onClick={() => togglePanel("where")}
        >
          <span className="search-label">
            Where
          </span>

          <span className="search-value">
            {destination || "Search destinations"}
          </span>
        </button>


        <div className="search-divider" />


        {/* WHEN */}

        <button
          className={`search-item search-when ${
            activePanel === "when"
              ? "search-item-active"
              : ""
          }`}
          onClick={() => togglePanel("when")}
        >
          <span className="search-label">
            When
          </span>

          <span className="search-value">
            Add dates
          </span>
        </button>


        <div className="search-divider" />


        {/* WHO */}

        <button
          className={`search-item search-who ${
            activePanel === "who"
              ? "search-item-active"
              : ""
          }`}
          onClick={() => togglePanel("who")}
        >

          <div className="who-content">

            <span className="search-label">
              Who
            </span>

            <span className="search-value">
              {totalGuests === 0
                ? "Add guests"
                : `${totalGuests} guest${
                    totalGuests > 1 ? "s" : ""
                  }`}
            </span>

          </div>

          <span className="search-button">
            🔍
            <span className="search-button-text">
              Search
            </span>
          </span>

        </button>

      </div>


      {/* =================================
          WHERE PANEL
      ================================= */}

      {activePanel === "where" && (
        <div
          className="search-panel destination-panel"
          onClick={(event) =>
            event.stopPropagation()
          }
        >

          <div className="panel-title">
            Suggested destinations
          </div>

          <button
            className="destination-option"
            onClick={() =>
              setDestination("Nearby")
            }
          >
            <div className="destination-icon blue">
              ➤
            </div>

            <div>
              <strong>Nearby</strong>
              <span>Find what’s around you</span>
            </div>
          </button>


          <button
            className="destination-option"
            onClick={() =>
              setDestination("Noida, Uttar Pradesh")
            }
          >
            <div className="destination-icon pink">
              ▦
            </div>

            <div>
              <strong>Noida, Uttar Pradesh</strong>
              <span>Near you</span>
            </div>
          </button>


          <button
            className="destination-option"
            onClick={() =>
              setDestination("North Goa, Goa")
            }
          >
            <div className="destination-icon orange">
              🏖
            </div>

            <div>
              <strong>North Goa, Goa</strong>
              <span>Popular beach destination</span>
            </div>
          </button>


          <button
            className="destination-option"
            onClick={() =>
              setDestination("Dehradun, Uttarakhand")
            }
          >
            <div className="destination-icon green">
              🏡
            </div>

            <div>
              <strong>Dehradun, Uttarakhand</strong>
              <span>For nature lovers</span>
            </div>
          </button>


          <button
            className="destination-option"
            onClick={() =>
              setDestination("New Delhi, Delhi")
            }
          >
            <div className="destination-icon green">
              🏙
            </div>

            <div>
              <strong>New Delhi, Delhi</strong>
              <span>For sights like India Gate</span>
            </div>
          </button>


          <button
            className="destination-option"
            onClick={() =>
              setDestination("Manali, Himachal Pradesh")
            }
          >
            <div className="destination-icon green">
              🏔
            </div>

            <div>
              <strong>Manali, Himachal Pradesh</strong>
              <span>Great for winter getaways</span>
            </div>
          </button>

        </div>
      )}


      {/* =================================
          WHEN PANEL
      ================================= */}

      {activePanel === "when" && (
        <div
          className="search-panel calendar-panel"
          onClick={(event) =>
            event.stopPropagation()
          }
        >

          <div className="calendar-toggle">
            <button className="calendar-toggle-active">
              Dates
            </button>

            <button>
              Flexible
            </button>
          </div>


          <div className="calendar-header">

            <button>‹</button>

            <h3>September 2026</h3>

            <h3>October 2026</h3>

            <button>›</button>

          </div>


          <div className="calendar-months">

            <CalendarMonth
              month="September 2026"
              startDay={2}
              days={30}
            />

            <CalendarMonth
              month="October 2026"
              startDay={4}
              days={31}
            />

          </div>


          <div className="date-options">

            <button className="date-option-active">
              Exact dates
            </button>

            <button>± 1 day</button>
            <button>± 2 days</button>
            <button>± 3 days</button>
            <button>± 7 days</button>
            <button>± 14 days</button>

          </div>

        </div>
      )}


      {/* =================================
          WHO PANEL
      ================================= */}

      {activePanel === "who" && (
        <div
          className="search-panel guests-panel"
          onClick={(event) =>
            event.stopPropagation()
          }
        >

          <GuestRow
            title="Adults"
            subtitle="Ages 13 or above"
            value={guests.adults}
            onMinus={() =>
              updateGuest("adults", -1)
            }
            onPlus={() =>
              updateGuest("adults", 1)
            }
          />

          <GuestRow
            title="Children"
            subtitle="Ages 2–12"
            value={guests.children}
            onMinus={() =>
              updateGuest("children", -1)
            }
            onPlus={() =>
              updateGuest("children", 1)
            }
          />

          <GuestRow
            title="Infants"
            subtitle="Under 2"
            value={guests.infants}
            onMinus={() =>
              updateGuest("infants", -1)
            }
            onPlus={() =>
              updateGuest("infants", 1)
            }
          />

          <GuestRow
            title="Pets"
            subtitle="Bringing a service animal?"
            value={guests.pets}
            onMinus={() =>
              updateGuest("pets", -1)
            }
            onPlus={() =>
              updateGuest("pets", 1)
            }
          />

        </div>
      )}

    </div>
  );
}


/* ========================================
   CALENDAR
======================================== */

function CalendarMonth({
  month,
  startDay,
  days,
}: {
  month: string;
  startDay: number;
  days: number;
}) {
  const dayNames = [
    "S",
    "M",
    "T",
    "W",
    "T",
    "F",
    "S",
  ];

  const cells = [];

  for (let i = 0; i < startDay; i++) {
    cells.push(
      <span key={`empty-${i}`} />
    );
  }

  for (let day = 1; day <= days; day++) {
    cells.push(
      <button key={day}>
        {day}
      </button>
    );
  }

  return (
    <div className="calendar-month">

      <h3>{month}</h3>

      <div className="calendar-days">
        {dayNames.map((day, index) => (
          <span key={index}>
            {day}
          </span>
        ))}

        {cells}

      </div>

    </div>
  );
}


/* ========================================
   GUEST ROW
======================================== */

function GuestRow({
  title,
  subtitle,
  value,
  onMinus,
  onPlus,
}: {
  title: string;
  subtitle: string;
  value: number;
  onMinus: () => void;
  onPlus: () => void;
}) {
  return (
    <div className="guest-row">

      <div className="guest-info">

        <strong>{title}</strong>

        <span>{subtitle}</span>

      </div>

      <div className="guest-controls">

        <button
          className={value === 0 ? "disabled" : ""}
          onClick={onMinus}
        >
          −
        </button>

        <span>{value}</span>

        <button onClick={onPlus}>
          +
        </button>

      </div>

    </div>
  );
}